INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62759641', 62759641, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Penyediaan Tenaga Ahli Pemetaan Pendataan bidang tanah, pengembangan sistem informasi pertanahan, dan fasilitasi Reforma Agraria', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 88000000, 'January 2026', 'APBD', 1, 1, '1 orang 8 bulan', 'Adapun kebutuhan tugas Tenaga Ahli ini meliputi, antara Lain : 1. menyusun rencana kerja dan metodologi pelaksanaan kegiatan 2. melakukan supervisi, koordinasi, serta monitoring terhadap seluruh tahapan pekerjaan 3. memberikan arahan teknis kepada Senior Assistant Professional Staff 4. menyusun analisis, pembahasan, dan rekomendasi berdasarkan hasil kegiatan 5. menyusun laporan-laporan kegiatan sesuai ketentuan yang berlaku 6. melakukan komunikasi dan koordinasi dengan PPTK dan PPK terkait pencapaian output kegiatan', 'Pendidikan minimal S1 jurusan Geodesi/Geografi/Geoinformatika/Geomatika dengan pengalaman minimal 4 tahun, memiliki pengalaman kerja dalam kegiatan perencanaan, kajian, atau analisis data, pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan), memiliki pengalaman kerja dalam kegiatan perencanaan, kajian, atau analisis data, mampu melakukan koordinasi, komunikasi, dan penyusunan dokumen teknis, mampu mengoperasikan komputer dan aplikasi pendukung pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 813195);
