INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63260053', 63260053, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR KEKARANTINAAN KESEHATAN TANJUNG PRIOK', 'Smart TV 98 inch', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Utara (Kota)', 199000000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1 Bh', 'Pengadaan Fasilitas Perkantoran (Smart TV 98 Inch)', 'Ukuran Layar: 98 inci (sekitar 218 cm lebar). Resolusi: 4K UHD (3840 x 2160). Teknologi Panel: Seringkali QLED atau HQLED untuk warna lebih baik. Refresh Rate: 100Hz, 120Hz, atau bahkan 144Hz untuk gerakan sangat halus. Prosesor Gambar: Quantum Processor 4K atau AiPQ Processor untuk peningkatan kualitas. HDR: Dukungan untuk HDR10+, Dolby Vision, HLG untuk kontras dan detail lebih baik. Koneksi Nirkabel: Wi-Fi 5/6 & Bluetooth 5.2. Port: HDMI (sering kali 3-4 port, beberapa mendukung 4K@120Hz), USB (1-2 port), Ethernet (LAN), Optical Out. Asisten Suara: Google Assistant, Bixby. Fitur Lain: SmartThings (Samsung), Chromecast Built-in (Google TV), Apple AirPlay, Gaming Mode (ALLM, VRR, FreeSync), Auto Game Mode. Audio Teknologi Suara: Dolby Atmos, DTS, 2.1 Channel Desain & Fisik Dimensi (sekitar): Lebar 218 cm, Tinggi 122-130 cm Desain: Bezel tipis, frameless', 199000000, 'high', 'Pengadaan 1 unit Smart TV 98 inci dengan spesifikasi premium untuk fasilitas perkantoran pada instansi kesehatan tampak tidak proporsional terhadap kebutuhan kerja umum. Ukuran sangat besar dan fitur hiburan/kelas konsumen seperti gaming mode, refresh rate tinggi, asisten suara, dan Dolby Atmos mengindikasikan spesifikasi berlebih untuk fungsi kantor, sehingga seluruh nilai pengadaan layak dicermati sebagai potensi pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 815342);
