INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62760125', 62760125, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultansi Individual Penyusunan Kajian Analisis Efektivitas TKD terhadap Pembangunan Kewilayahan Pasca Kebijakan Inpres Direktorat Pemerintahan, Keuangan Daerah, Dan Transfer Ke Daerah', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99990000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Membangun kerangka kerja kegiatan, termasuk timeline, instrumen dan mekanisme pelaksanaan analisis efektivitas TKD terhadap pembangunan kewilayahan pasca kebijakan Inpres; 2. Menginventarisasi dan identifikasi data, informasi, serta menyusun kaidah penelaahan regulasi terkait Efektivitas TKD terhadap Pembangunan Kewilayahan; 3. Melakukan peninjauan terhadap arah kebijakan dan isu strategis Efektivitas TKD terhadap Pembangunan Kewilayahan Pasca Kebijakan Inpres dan pelaksanaan APBN 2026; 4. Melakukan analisis Efektivitas TKD terhadap Pembangunan Kewilayahan pasca Kebijakan Inpres dan pelaksanaan APBN 2026 terhadap target pembangunan dalam RPJMN 2025- 2029 dan RKP 2025; 5. Menyusun hasil analisis Efektivitas TKD terhadap Pembangunan Kewilayahan Pasca Kebijakan Inpres dan pelaksanaan APBN 2026 dalam bentuk pemetaan dan visualisasi yang informatif; 6. Menyusun rumusan rancangan rekomendasi dan strategi penguatan kebijakan TKD dalam mendukung pembangunan kewilayahan;', '1. Merupakan Tenaga Ahli dalam negeri (Dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 2. Memiliki NPWP dan status valid Konfirmasi Status Wajib Pajak (KSWP) 3. Memiliki pendidikan minimal Strata Satu (S1) di bidang Pengembangan Wilayah/ Perencanaan Wilayah dan Kota/Manajemen Kebijakan Publik; 4. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman sub kontrak; 5. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 816130);
