INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63239673', 63239673, 'analyze_legacy', 'Badan Narkotika Nasional', 'central', 'BADAN NARKOTIKA NASIONAL KABUPATEN SIDOARJO', 'Operasional dan Pemeliharaan Kantor', 'Barang', 'Pengadaan Langsung', 'Jawa Timur, Sidoarjo (Kab.)', 1219580000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Belanja Honor Operasional Satuan Kerja; 2. Belanja Keperluan Perkantoran; 3. Belanja Honor Operasional Satuan Kerja; 4. Belanja Keperluan Perkantoran; 5. Belanja Keperluan Perkantoran; 6. Belanja Honor Operasional Satuan Kerja; 7. Belanja Honor Operasional Satuan Kerja; 8. Belanja Bahan; 9. Belanja Barang Persediaan Barang Konsumsi; 10. Belanja Langganan Listrik; 11. Belanja Langganan Telepon; 12. Belanja Langganan Air; 13. Belanja Sewa; 14. Belanja Sewa; 15. Belanja Jasa Lainnya; 16. Belanja Pemeliharaan Gedung dan Bangunan; 17. Belanja Pemeliharaan Peralatan dan Mesin; 18. Belanja Pemeliharaan Peralatan dan Mesin; 19. Belanja Perjalanan Dinas Biasa; 20. Belanja Perjalanan Dinas Dalam Kota; 21. Belanja Perjalanan Dinas Dalam Kota;', 'Belanja Honor Operasional Satuan Kerja Honorarium diberikan kepada pegawai/nonpegawai yang terlibat langsung dalam kegiatan operasional satuan kerja, sesuai tugas dan tanggung jawab yang ditetapkan. Pembayaran mengacu pada ketentuan peraturan perundang-undangan, standar biaya masukan, serta didukung dokumen penugasan dan laporan kegiatan. Belanja Keperluan Perkantoran Pengadaan barang penunjang operasional kantor seperti alat tulis kantor, perlengkapan administrasi, dan kebutuhan kerja harian. Barang harus baru, layak pakai, dan mendukung kelancaran administrasi perkantoran. Belanja Honor Operasional Satuan Kerja Digunakan untuk pembayaran honor pelaksana kegiatan operasional lainnya yang bersifat rutin maupun insidentil sesuai ketentuan yang berlaku dan kebutuhan satuan kerja. Belanja Keperluan Perkantoran Mencakup pengadaan perlengkapan pendukung kegiatan perencanaan, pelaporan, dan layanan administrasi kantor secara berkelanjutan. Belanja Keperluan Perkantoran Digunakan untuk memenuhi kebutuhan logistik perkantoran yang bersifat habis pakai guna mendukung pelaksanaan tugas dan fungsi organisasi. Belanja Honor Operasional Satuan Kerja Honorarium dibayarkan berdasarkan output pekerjaan, periode kerja, dan ketersediaan anggaran sesuai regulasi. Belanja Honor Operasional Satuan Kerja Pembayaran honor didukung oleh surat keputusan, daftar hadir, dan laporan pelaksanaan kegiatan. Belanja Bahan Pengadaan bahan pendukung kegiatan kantor atau kegiatan teknis lainnya yang bersifat habis pakai dan menunjang pelaksanaan program kerja. Belanja Barang Persediaan Barang Konsumsi Pengadaan barang konsumsi seperti makanan ringan dan minuman untuk mendukung rapat, koordinasi, dan kegiatan internal. Belanja Langganan Listrik Pembayaran biaya listrik kantor sesuai tagihan resmi penyedia layanan untuk menunjang operasional gedung. Belanja Langganan Telepon Pembayaran biaya layanan telepon kantor guna mendukung komunikasi kedinasan. Belanja Langganan Air Pembayaran biaya penggunaan air bersih kantor sesuai tagihan resmi penyedia layanan. Belanja Sewa Sewa gedung, ruangan, atau sarana pendukung kegiatan sesuai kebutuhan dan jangka waktu yang ditetapkan. Belanja Sewa Sewa peralatan atau fasilitas penunjang operasional dan kegiatan kedinasan. Belanja Jasa Lainnya Pengadaan jasa nonkonsultan yang mendukung operasional kantor, seperti jasa kebersihan, keamanan, atau layanan pendukung lainnya. Belanja Pemeliharaan Gedung dan Bangunan Kegiatan pemeliharaan ringan untuk menjaga kondisi gedung agar tetap layak fungsi dan aman digunakan. Belanja Pemeliharaan Peralatan dan Mesin Pemeliharaan rutin peralatan dan mesin kantor agar berfungsi optimal dan memperpanjang umur pakai. Belanja Pemeliharaan Peralatan dan Mesin Perbaikan ringan peralatan dan mesin yang mengalami gangguan operasional. Belanja Perjalanan Dinas Biasa Pembiayaan perjalanan dinas luar daerah untuk pelaksanaan tugas kedinasan sesuai surat tugas dan ketentuan yang berlaku. Belanja Perjalanan Dinas Dalam Kota Pembiayaan perjalanan dinas dalam wilayah kota untuk mendukung koordinasi dan pelaksanaan kegiatan. Belanja Perjalanan Dinas Dalam Kota Perjalanan dinas dalam kota yang bersifat rutin maupun insidentil sesuai kebutuhan operasional.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 818624);
